import type { NextConfig } from "next";
import bundleAnalyzer from '@next/bundle-analyzer';

const withBundleAnalyzer = bundleAnalyzer({
  enabled: process.env.ANALYZE === 'true',
});

const nextConfig: NextConfig = {
  webpack(config) {
    // Grab the existing rule that handles SVG imports
    const fileLoaderRule = config.module.rules.find((rule: any) =>
      rule.test?.test?.('.svg'),
    )

    config.module.rules.push(
      // Reapply the existing rule, but only for svg imports ending in ?url
      {
        ...fileLoaderRule,
        test: /\.svg$/i,
        resourceQuery: /url/, // *.svg?url
      },
      // Convert all other *.svg imports to React components
      {
        test: /\.svg$/i,
        issuer: fileLoaderRule.issuer,
        resourceQuery: { not: [...fileLoaderRule.resourceQuery.not, /url/] }, // exclude if *.svg?url
        use: ['@svgr/webpack'],
      },
    )

    // Modify the file loader rule to ignore *.svg, since we have it handled now.
    fileLoaderRule.exclude = /\.svg$/i

    return config
  },
  turbopack: {
    rules: {
      "*.svg": {
        loaders: ["@svgr/webpack"],
        as: "*.js",
      },
    },
  },
  images: {
    formats: ['image/avif', 'image/webp'],
    remotePatterns: [
      {
        protocol: 'https',
        hostname: 'images.unsplash.com',
      },
    ],
  },
  async headers() {
    return [
      {
        source: '/(.*)',
        headers: [
          {
            key: 'X-Frame-Options',
            value: 'DENY',
          },
          {
            key: 'X-Content-Type-Options',
            value: 'nosniff',
          },
          {
            key: 'Strict-Transport-Security',
            value: 'max-age=31536000; includeSubDomains; preload',
          },
        ],
      },
    ];
  },
};

export default withBundleAnalyzer(nextConfig);

const fs = require('fs');
const results = JSON.parse(fs.readFileSync('lint-results.json', 'utf8'));
const counts = {};
results.forEach(file => {
  file.messages.forEach(msg => {
    const rule = msg.ruleId;
    counts[rule] = (counts[rule] || 0) + 1;
  });
});
console.log(Object.entries(counts).sort((a,b) => b[1] - a[1]).slice(0, 20));

const fs = require('fs');
const path = require('path');

function walkDir(dir, callback) {
  fs.readdirSync(dir).forEach(f => {
    let dirPath = path.join(dir, f);
    let isDirectory = fs.statSync(dirPath).isDirectory();
    isDirectory ? 
      walkDir(dirPath, callback) : callback(path.join(dir, f));
  });
}

function processFile(filePath) {
  if (!filePath.endsWith('.tsx') && !filePath.endsWith('.jsx')) return;

  let content = fs.readFileSync(filePath, 'utf8');
  let hasChanges = false;

  // Replace imports
  const importRegex = /import\s+Link\s+from\s+['"]next\/link['"];?/g;
  if (importRegex.test(content)) {
    content = content.replace(importRegex, "import { TransitionLink } from '@/components/ui/TransitionLink';");
    hasChanges = true;
  }

  // Only replace tags if we replaced the import, or if it already has TransitionLink import but lingering <Link>
  // Actually, we should just replace `<Link` -> `<TransitionLink` if there is no local component named Link
  if (content.includes("import { TransitionLink }")) {
    const openingRegex = /<Link(\s|>)/g;
    const closingRegex = /<\/Link>/g;

    if (openingRegex.test(content)) {
      content = content.replace(openingRegex, "<TransitionLink$1");
      hasChanges = true;
    }
    if (closingRegex.test(content)) {
      content = content.replace(closingRegex, "</TransitionLink>");
      hasChanges = true;
    }
  }

  if (hasChanges) {
    fs.writeFileSync(filePath, content, 'utf8');
    console.log('Updated', filePath);
  }
}

walkDir('./src/app', processFile);
walkDir('./src/components', processFile);
console.log('Done!');

'use client';

import React, { useState } from 'react';
import { useMenu } from '@/hooks/useMenu';
import { db } from '@/lib/firebase';
import { doc, updateDoc, addDoc, collection } from 'firebase/firestore';
import type { MenuItem } from '@/types/firestore';
import { Search, Edit2, Check, X, Plus } from 'lucide-react';
import { Modal } from '@/components/molecules/feedback/Modal';

export default function AdminMenuPage() {
  const { items, loading } = useMenu();
  const [searchTerm, setSearchTerm] = useState('');
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);

  const handleToggleAvailable = async (item: MenuItem) => {
    try {
      await updateDoc(doc(db, 'menu_items', item.id), {
        available: !item.available
      });
    } catch (err) {
      console.error('Failed to toggle availability', err);
    }
  };

  const handleSaveEdit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;
    try {
      const { id, ...data } = editingItem;
      if (id === 'new') {
        await addDoc(collection(db, 'menu_items'), data);
      } else {
        await updateDoc(doc(db, 'menu_items', id), data);
      }
      setEditingItem(null);
    } catch (err) {
      console.error('Failed to save item', err);
    }
  };

  const handleAddNew = () => {
    setEditingItem({
      id: 'new',
      name: '',
      desc: '',
      price: 0,
      category: 'boxen',
      available: true,
      tags: [],
      icon: '',
      color: ''
    } as unknown as MenuItem);
  };

  const filteredItems = items.filter(item => 
    item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="p-8 max-w-6xl mx-auto">
      <div className="mb-8 flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h1 className="font-calistoga text-4xl text-charcoal mb-2">Menü Manager</h1>
          <p className="font-bold text-charcoal/60">Produkte, Preise und Verfügbarkeit verwalten</p>
        </div>

        <div className="flex gap-4 w-full md:w-auto">
          <div className="relative w-full md:w-72">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-charcoal/40" />
            <input 
              type="text" 
              placeholder="Suchen..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-12 pr-4 py-3 rounded-full bg-cream border border-peach focus:outline-none focus:border-terracotta font-bold text-charcoal placeholder:text-charcoal/40"
            />
          </div>
          <button 
            onClick={handleAddNew}
            className="flex items-center gap-2 bg-terracotta text-cream px-6 py-3 rounded-full font-bold shadow-clay hover:bg-brown transition-colors shrink-0"
          >
            <Plus className="w-5 h-5" />
            Neues Produkt
          </button>
        </div>
      </div>

      {loading ? (
        <div className="animate-pulse flex flex-col gap-4">
          {[1,2,3,4,5].map(i => <div key={i} className="h-20 bg-cream rounded-2xl" />)}
        </div>
      ) : (
        <div className="bg-cream rounded-3xl overflow-hidden shadow-sm border border-peach">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-peach">
                <th className="py-4 px-6 font-calistoga text-terracotta">Produkt</th>
                <th className="py-4 px-6 font-calistoga text-terracotta hidden md:table-cell">Kategorie</th>
                <th className="py-4 px-6 font-calistoga text-terracotta">Preis</th>
                <th className="py-4 px-6 font-calistoga text-terracotta text-center">Verfügbar</th>
                <th className="py-4 px-6 font-calistoga text-terracotta text-right">Aktion</th>
              </tr>
            </thead>
            <tbody>
              {filteredItems.map(item => (
                <tr key={item.id} className="border-b border-peach/50 hover:bg-peach/10 transition-colors">
                  <td className="py-4 px-6">
                    <div className="font-bold text-charcoal">{item.name}</div>
                    <div className="text-xs text-charcoal/60 line-clamp-1 max-w-xs">{item.desc}</div>
                  </td>
                  <td className="py-4 px-6 hidden md:table-cell">
                    <span className="bg-sand px-3 py-1 rounded-full text-xs font-bold text-brown uppercase tracking-wider">
                      {item.category}
                    </span>
                  </td>
                  <td className="py-4 px-6 font-bold text-charcoal">
                    {typeof item.price === 'number' ? item.price.toFixed(2).replace('.', ',') : item.price} €
                  </td>
                  <td className="py-4 px-6 text-center">
                    <button 
                      onClick={() => handleToggleAvailable(item)}
                      className={`relative inline-flex h-7 w-12 items-center rounded-full transition-colors ${item.available ? 'bg-terracotta' : 'bg-charcoal/20'}`}
                    >
                      <span className={`inline-block h-5 w-5 transform rounded-full bg-cream transition-transform shadow-sm ${item.available ? 'translate-x-6' : 'translate-x-1'}`} />
                    </button>
                  </td>
                  <td className="py-4 px-6 text-right">
                    <button 
                      onClick={() => setEditingItem(item)}
                      className="p-2 text-charcoal/60 hover:text-terracotta hover:bg-peach/30 rounded-full transition-colors"
                    >
                      <Edit2 className="w-5 h-5" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Edit Modal */}
      <Modal 
        isOpen={!!editingItem} 
        onClose={() => setEditingItem(null)} 
        title={editingItem?.id === 'new' ? "Neues Produkt anlegen" : "Produkt bearbeiten"}
      >
        {editingItem && (
          <form onSubmit={handleSaveEdit} className="flex flex-col gap-4">
            <div>
              <label className="block text-sm font-bold text-brown mb-1">Name</label>
              <input 
                type="text" 
                value={editingItem.name} 
                onChange={e => setEditingItem({ ...editingItem, name: e.target.value })}
                className="w-full px-4 py-3 rounded-xl bg-sand border border-peach focus:outline-none focus:border-terracotta font-bold text-charcoal"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-bold text-brown mb-1">Preis (€)</label>
                <input 
                  type="number" 
                  step="0.01"
                  value={editingItem.price} 
                  onChange={e => setEditingItem({ ...editingItem, price: parseFloat(e.target.value) })}
                  className="w-full px-4 py-3 rounded-xl bg-sand border border-peach focus:outline-none focus:border-terracotta font-bold text-charcoal"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-brown mb-1">Kategorie</label>
                <input 
                  type="text" 
                  value={editingItem.category} 
                  onChange={e => setEditingItem({ ...editingItem, category: e.target.value })}
                  className="w-full px-4 py-3 rounded-xl bg-sand border border-peach focus:outline-none focus:border-terracotta font-bold text-charcoal"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-brown mb-1">Beschreibung</label>
              <textarea 
                value={editingItem.desc} 
                onChange={e => setEditingItem({ ...editingItem, desc: e.target.value })}
                className="w-full px-4 py-3 rounded-xl bg-sand border border-peach focus:outline-none focus:border-terracotta font-bold text-charcoal min-h-[100px] resize-none"
              />
            </div>

            <button 
              type="submit"
              className="mt-4 bg-terracotta text-cream py-3 rounded-xl font-bold text-lg shadow-clay hover:bg-brown transition-colors"
            >
              Speichern
            </button>
          </form>
        )}
      </Modal>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { useStoreSettings } from "@/hooks/useStoreSettings";
import { db } from "@/lib/firebase";
import {
  doc,
  updateDoc,
  setDoc,
  collection,
  getDocs,
  deleteDoc,
} from "firebase/firestore";
import {
  Power,
  Clock,
  Megaphone,
  Calendar,
  AlertTriangle,
  Tag,
  Trash2,
  Plus,
} from "lucide-react";
import { useToastStore } from "@/store/useToastStore";

export default function AdminSettingsPage() {
  const { settings, loading } = useStoreSettings();
  const { addToast } = useToastStore();

  const [localSettings, setLocalSettings] = useState({
    currentWaitTime: 15,
    bannerText: "",
    emergencyNotice: "",
    openingHours: "Mi-Sa 12-19 Uhr, So 13-19 Uhr",
    deliveryZones: "35576, 35578",
  });
  const [isSaving, setIsSaving] = useState(false);

  const [promoCodes, setPromoCodes] = useState<any[]>([]);
  const [newPromo, setNewPromo] = useState({
    code: "",
    type: "fixed",
    amount: 0,
  });

  const fetchPromoCodes = async () => {
    try {
      const snap = await getDocs(collection(db, "promo_codes"));
      setPromoCodes(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    } catch (e) {
      console.error(e);
    }
  };

  useEffect(() => {
    if (settings) {
      setLocalSettings({
        currentWaitTime: settings.currentWaitTime || 15,
        bannerText: settings.bannerText || "",
        emergencyNotice: (settings as any).emergencyNotice || "",
        openingHours:
          (settings as any).openingHours || "Mi-Sa 12-19 Uhr, So 13-19 Uhr",
        deliveryZones: (settings as any).deliveryZones || "35576, 35578",
      });
    }
    fetchPromoCodes();
  }, [settings]);

  const handleToggleOnline = async () => {
    if (!settings) return;
    try {
      await updateDoc(doc(db, "store_settings", "general"), {
        isOnline: !settings.isOnline,
      });
      addToast({
        title: !settings.isOnline ? "Shop ist Online" : "Notfall-Stopp aktiv",
        message: !settings.isOnline
          ? "Bestellungen werden jetzt angenommen."
          : "Bestellannahme gestoppt.",
        type: !settings.isOnline ? "success" : "error",
      });
    } catch (err) {
      console.error(err);
      addToast({
        title: "Fehler",
        message: "Status konnte nicht geändert werden.",
        type: "error",
      });
    }
  };

  const handleSaveSettings = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await setDoc(
        doc(db, "store_settings", "general"),
        {
          ...localSettings,
        },
        { merge: true },
      );
      addToast({
        title: "Gespeichert",
        message: "Einstellungen wurden erfolgreich aktualisiert.",
        type: "success",
      });
    } catch (err) {
      console.error(err);
      addToast({
        title: "Fehler",
        message: "Speichern fehlgeschlagen.",
        type: "error",
      });
    } finally {
      setIsSaving(false);
    }
  };

  const handleAddPromo = async () => {
    if (!newPromo.code || newPromo.amount <= 0) return;
    try {
      const codeUpper = newPromo.code.toUpperCase();
      await setDoc(doc(db, "promo_codes", codeUpper), {
        type: newPromo.type,
        amount: newPromo.amount,
        active: true,
      });
      setNewPromo({ code: "", type: "fixed", amount: 0 });
      fetchPromoCodes();
      addToast({ title: "Gutschein erstellt", type: "success" });
    } catch (e) {
      console.error(e);
    }
  };

  const handleDeletePromo = async (id: string) => {
    try {
      await deleteDoc(doc(db, "promo_codes", id));
      fetchPromoCodes();
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <div className="mb-10">
        <h1 className="font-calistoga text-4xl text-charcoal mb-2">
          Einstellungen
        </h1>
        <p className="font-bold text-charcoal/60">
          Store-Status, Wartezeiten und Texte verwalten
        </p>
      </div>

      {loading ? (
        <div className="animate-pulse flex flex-col gap-8">
          <div className="h-32 bg-cream rounded-3xl" />
          <div className="h-64 bg-cream rounded-3xl" />
        </div>
      ) : (
        <div className="flex flex-col gap-8">
          {/* Emergency Stop Toggle */}
          <div
            className={`p-8 rounded-3xl flex flex-col md:flex-row items-center justify-between gap-6 transition-colors duration-500 ${settings?.isOnline ? "bg-mint/20 border-mint/40" : "bg-red-500/10 border-red-500/20"} border-2`}
          >
            <div>
              <h2 className="font-calistoga text-2xl text-charcoal mb-2 flex items-center gap-3">
                <Power
                  className={settings?.isOnline ? "text-mint" : "text-red-500"}
                />
                {settings?.isOnline
                  ? "Store ist Online"
                  : "Store ist Offline (Notfall-Stopp)"}
              </h2>
              <p className="font-bold text-charcoal/70">
                {settings?.isOnline
                  ? "Kunden können aktuell Bestellungen aufgeben."
                  : "Die Bestellannahme ist komplett deaktiviert. Der Shop zeigt einen Wartungshinweis."}
              </p>
            </div>

            <button
              onClick={handleToggleOnline}
              className={`relative flex h-14 w-28 items-center rounded-full p-2 transition-colors duration-500 shrink-0 ${settings?.isOnline ? "bg-mint" : "bg-red-500"}`}
            >
              <motion.div
                layout
                transition={{ type: "spring", stiffness: 500, damping: 30 }}
                className="h-10 w-10 rounded-full bg-white shadow-lg flex items-center justify-center"
              >
                <Power
                  className={`w-5 h-5 ${settings?.isOnline ? "text-mint" : "text-red-500"}`}
                />
              </motion.div>
              {/* This span pushes the toggle to the right if online using flex properties (e.g. justify-end) 
                  Or we can just rely on layout animation inside a flex-start/flex-end container */}
              <div className="absolute inset-0 flex items-center justify-between px-4 pointer-events-none">
                <span
                  className={`text-white font-bold text-xs ${settings?.isOnline ? "opacity-100" : "opacity-0"}`}
                >
                  ON
                </span>
                <span
                  className={`text-white font-bold text-xs ${!settings?.isOnline ? "opacity-100" : "opacity-0"}`}
                >
                  OFF
                </span>
              </div>
            </button>
          </div>

          {/* Settings Form */}
          <form
            onSubmit={handleSaveSettings}
            className="bg-cream p-8 rounded-3xl border border-peach flex flex-col gap-6"
          >
            <h2 className="font-calistoga text-2xl text-charcoal mb-2 border-b border-peach pb-4">
              Allgemeine Einstellungen
            </h2>

            <div>
              <label className="flex items-center gap-2 text-sm font-bold text-brown mb-2">
                <Clock className="w-4 h-4" /> Aktuelle Wartezeit (Minuten)
              </label>
              <input
                type="number"
                value={localSettings.currentWaitTime}
                onChange={(e) =>
                  setLocalSettings({
                    ...localSettings,
                    currentWaitTime: parseInt(e.target.value) || 0,
                  })
                }
                className="w-full px-4 py-3 rounded-xl bg-sand border border-peach focus:outline-none focus:border-terracotta font-bold text-charcoal max-w-xs"
              />
              <p className="text-xs text-charcoal/50 mt-2 font-bold">
                Wird im Checkout als geschätzte Zubereitungszeit angezeigt.
              </p>
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-bold text-brown mb-2">
                <Megaphone className="w-4 h-4" /> Promo-Banner Text
              </label>
              <input
                type="text"
                value={localSettings.bannerText}
                onChange={(e) =>
                  setLocalSettings({
                    ...localSettings,
                    bannerText: e.target.value,
                  })
                }
                placeholder="z.B. Heute 10% auf alle Bubble Waffles!"
                className="w-full px-4 py-3 rounded-xl bg-sand border border-peach focus:outline-none focus:border-terracotta font-bold text-charcoal"
              />
              <p className="text-xs text-charcoal/50 mt-2 font-bold">
                Wird als Marquee im Header angezeigt. Leer lassen zum
                Ausblenden.
              </p>
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-bold text-brown mb-2">
                <AlertTriangle className="w-4 h-4" /> Notfall-Banner Text
              </label>
              <input
                type="text"
                value={localSettings.emergencyNotice}
                onChange={(e) =>
                  setLocalSettings({
                    ...localSettings,
                    emergencyNotice: e.target.value,
                  })
                }
                placeholder="z.B. Wir haben heute wegen Krankheit geschlossen."
                className="w-full px-4 py-3 rounded-xl bg-sand border border-peach focus:outline-none focus:border-terracotta font-bold text-charcoal"
              />
              <p className="text-xs text-charcoal/50 mt-2 font-bold">
                Wird nur angezeigt, wenn der Store Offline geschaltet ist.
              </p>
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-bold text-brown mb-2">
                <Calendar className="w-4 h-4" /> Öffnungszeiten (Anzeige)
              </label>
              <input
                type="text"
                value={localSettings.openingHours}
                onChange={(e) =>
                  setLocalSettings({
                    ...localSettings,
                    openingHours: e.target.value,
                  })
                }
                className="w-full px-4 py-3 rounded-xl bg-sand border border-peach focus:outline-none focus:border-terracotta font-bold text-charcoal"
              />
            </div>

            <div>
              <label className="flex items-center gap-2 text-sm font-bold text-brown mb-2">
                Lieferzonen (PLZ, kommagetrennt)
              </label>
              <input
                type="text"
                value={localSettings.deliveryZones}
                onChange={(e) =>
                  setLocalSettings({
                    ...localSettings,
                    deliveryZones: e.target.value,
                  })
                }
                className="w-full px-4 py-3 rounded-xl bg-sand border border-peach focus:outline-none focus:border-terracotta font-bold text-charcoal"
              />
            </div>

            <button
              type="submit"
              disabled={isSaving}
              className="mt-6 bg-terracotta text-cream py-4 rounded-xl font-bold text-lg shadow-clay hover:bg-brown transition-colors disabled:opacity-50"
            >
              {isSaving ? "Speichert..." : "Einstellungen speichern"}
            </button>
          </form>

          {/* Promo Codes Section */}
          <div className="bg-cream p-8 rounded-3xl border border-peach flex flex-col gap-6">
            <h2 className="font-calistoga text-2xl text-charcoal mb-2 border-b border-peach pb-4 flex items-center gap-2">
              <Tag className="w-6 h-6 text-terracotta" /> Promo Codes
            </h2>

            <div className="bg-sand p-4 rounded-2xl flex gap-3 items-end">
              <div className="flex-1">
                <label className="block text-xs font-bold text-brown mb-1">
                  Code
                </label>
                <input
                  type="text"
                  value={newPromo.code}
                  onChange={(e) =>
                    setNewPromo({ ...newPromo, code: e.target.value })
                  }
                  placeholder="z.B. SUMMER24"
                  className="w-full bg-cream border border-peach px-3 py-2 rounded-xl outline-none font-bold uppercase"
                />
              </div>
              <div className="w-32">
                <label className="block text-xs font-bold text-brown mb-1">
                  Typ
                </label>
                <select
                  value={newPromo.type}
                  onChange={(e) =>
                    setNewPromo({ ...newPromo, type: e.target.value })
                  }
                  className="w-full bg-cream border border-peach px-3 py-2 rounded-xl outline-none font-bold"
                >
                  <option value="fixed">€ Rabatt</option>
                  <option value="percent">% Rabatt</option>
                </select>
              </div>
              <div className="w-24">
                <label className="block text-xs font-bold text-brown mb-1">
                  Wert
                </label>
                <input
                  type="number"
                  value={newPromo.amount || ""}
                  onChange={(e) =>
                    setNewPromo({
                      ...newPromo,
                      amount: parseFloat(e.target.value) || 0,
                    })
                  }
                  className="w-full bg-cream border border-peach px-3 py-2 rounded-xl outline-none font-bold"
                />
              </div>
              <button
                onClick={handleAddPromo}
                className="bg-terracotta text-cream px-4 py-2 rounded-xl font-bold mb-[1px]"
              >
                <Plus size={20} />
              </button>
            </div>

            <div className="space-y-3">
              {promoCodes.map((promo) => (
                <div
                  key={promo.id}
                  className="flex justify-between items-center bg-white p-4 rounded-2xl border border-peach shadow-sm"
                >
                  <div className="flex items-center gap-3">
                    <div className="font-calistoga text-lg text-terracotta">
                      {promo.id}
                    </div>
                    <span className="px-2 py-1 bg-sand text-brown rounded-full text-[10px] font-black uppercase tracking-widest">
                      {promo.type === "fixed"
                        ? `${promo.amount}€`
                        : `${promo.amount}%`}
                    </span>
                  </div>
                  <button
                    onClick={() => handleDeletePromo(promo.id)}
                    className="text-charcoal/40 hover:text-red-500 transition-colors"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              ))}
              {promoCodes.length === 0 && (
                <div className="text-sm font-bold text-charcoal/50">
                  Keine Gutscheincodes vorhanden.
                </div>
              )}
            </div>
          </div>

          {/* Database Seed Section */}
          <div className="bg-cream p-8 rounded-3xl border border-peach flex flex-col gap-6">
            <h2 className="font-calistoga text-2xl text-charcoal mb-2 border-b border-peach pb-4 text-red-600">
              Entwickler-Optionen
            </h2>
            <p className="font-bold text-charcoal/70">
              Mit dieser Option kannst du das Backend mit den anfänglichen
              Demo-Daten (Menü, Analytics, Bestellungen) befüllen.
            </p>
            <button
              onClick={async () => {
                if (
                  confirm(
                    "Achtung: Dies fügt Dummy-Daten zur Datenbank hinzu. Fortfahren?",
                  )
                ) {
                  try {
                    const res = await fetch("/api/admin/seed", {
                      method: "POST",
                    });
                    if (res.ok) {
                      addToast({
                        title: "Erfolg",
                        message: "Datenbank wurde befüllt!",
                        type: "success",
                      });
                    } else {
                      addToast({
                        title: "Fehler",
                        message: "Seed fehlgeschlagen",
                        type: "error",
                      });
                    }
                  } catch (e) {
                    addToast({
                      title: "Fehler",
                      message: "Seed fehlgeschlagen",
                      type: "error",
                    });
                  }
                }
              }}
              className="bg-red-500 text-white py-3 px-6 rounded-xl font-bold shadow-clay hover:bg-red-600 transition-colors self-start"
            >
              Datenbank initialisieren (Seed)
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

