function LegalIcon({
  children,
  color = "#CC624C",
}: {
  children: React.ReactNode;
  color?: string;
}) {
  return (
    <div
      style={{
        width: 32,
        height: 32,
        borderRadius: "50%",
        background: color,
        color: "#fefefe",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
      }}
    >
      {children}
    </div>
  );
}

/** Collapsible accordion section */
function AccordionSection({
  icon,
  number,
  title,
  children,
  defaultOpen = false,
}: {
  icon: React.ReactNode;
  number: string;
  title: string;
  children: React.ReactNode;
  defaultOpen?: boolean;
}) {
  const [open, setOpen] = useState(defaultOpen);

  return (
    <motion.div
      layout
      style={{
        background: open ? "rgba(245,239,232,0.6)" : "transparent",
        borderRadius: 18,
        border: open
          ? "1px solid rgba(228,192,168,0.4)"
          : "1px solid transparent",
        marginBottom: 8,
        overflow: "hidden",
        transition: "background 0.3s, border 0.3s",
      }}
    >
      <button
        onClick={() => setOpen(!open)}
        aria-expanded={open}
        style={{
          width: "100%",
          display: "flex",
          alignItems: "center",
          gap: 12,
          padding: "16px 20px",
          background: "none",
          border: "none",
          cursor: "pointer",
          textAlign: "left",
        }}
      >
        <LegalIcon>{icon}</LegalIcon>
        <div style={{ flex: 1 }}>
          <span
            style={{
              fontFamily: "var(--font-nunito), sans-serif",
              fontSize: "0.72rem",
              fontWeight: 800,
              color: "#CC624C",
              textTransform: "uppercase",
              letterSpacing: "0.08em",
            }}
          >
            {number}
          </span>
          <div
            style={{
              fontFamily: "var(--font-calistoga), serif",
              fontSize: "1.05rem",
              color: "#2d1f19",
            }}
          >
            {title}
          </div>
        </div>
        <motion.div
          animate={{ rotate: open ? 180 : 0 }}
          transition={{ type: "spring", stiffness: 300, damping: 25 }}
        >
          <ChevronDown size={20} color="#9a7060" />
        </motion.div>
      </button>

      <AnimatePresence initial={false}>
        {open && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
            style={{ overflow: "hidden" }}
          >
            <div
              style={{
                padding: "0 20px 20px 64px",
                fontFamily: "var(--font-nunito), sans-serif",
                color: "#5c3d35",
                fontSize: "0.9rem",
                lineHeight: 1.72,
              }}
            >
              {children}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

/** Cookie pill badge */
function CookieBadge({ category }: { category: string }) {
  const colors: Record<string, { bg: string; text: string }> = {
    Notwendig: { bg: "#CC624C", text: "#fefefe" },
    Funktional: { bg: "#E4C0A8", text: "#2d1f19" },
    Statistik: { bg: "#9a7060", text: "#fefefe" },
    Marketing: { bg: "#5c3d35", text: "#fefefe" },
  };
  const c = colors[category] || colors.Notwendig;
  return (
    <span
      style={{
        background: c.bg,
        color: c.text,
        padding: "3px 12px",
        borderRadius: 50,
        fontSize: "0.7rem",
        fontWeight: 800,
        letterSpacing: "0.03em",
      }}
    >
      {category}
    </span>
  );
}

/** Right card — one of the Betroffenenrechte */
function RightCard({ right, article }: { right: string; article: string }) {
  return (
    <motion.div
