        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          marginBottom: 2,
        }}
      >
        <CheckCircle2 size={14} color="#CC624C" />
        <span
          style={{ fontWeight: 800, color: "#2d1f19", fontSize: "0.85rem" }}
        >
          {right}
        </span>
      </div>
      <span style={{ fontSize: "0.72rem", color: "#9a7060", fontWeight: 600 }}>
