export default function ProfilePage() {
  const { user, dbUser } = useAuth();
  const { orders } = useOrders();

  const [isEditingData, setIsEditingData] = useState(false);
  const [name, setName] = useState(dbUser?.name || user?.displayName || "");
  const [phone, setPhone] = useState(dbUser?.phone || "");
  const [birthday, setBirthday] = useState(dbUser?.birthday || "");
  const [savingData, setSavingData] = useState(false);

  const [addresses, setAddresses] = useState<any[]>(dbUser?.addresses || []);
  const [isAddingAddress, setIsAddingAddress] = useState(false);
  const [newAddress, setNewAddress] = useState({ street: "", zip: "", city: "" });

  const orderCount = orders.length;

  const handleLogout = async () => {
    await signOut(auth);
  };

  const handleSaveData = async () => {
    if (!user) return;
    setSavingData(true);
    try {
      await updateDoc(doc(db, 'users', user.uid), {
        name,
        phone,
        birthday
      });
      setIsEditingData(false);
    } catch (e) {
      console.error(e);
      alert("Fehler beim Speichern");
    } finally {
      setSavingData(false);
    }
  };

  const handleAddAddress = async () => {
    if (!user) return;
    if (!newAddress.street || !newAddress.zip || !newAddress.city) return;
    setSavingData(true);
    try {
      const updated = [...addresses, newAddress];
      await updateDoc(doc(db, 'users', user.uid), {
        addresses: updated
      });
      setAddresses(updated);
      setIsAddingAddress(false);
      setNewAddress({ street: "", zip: "", city: "" });
    } catch (e) {
      console.error(e);
    } finally {
      setSavingData(false);
    }
  };

  const handleDeleteAddress = async (index: number) => {
    if (!user) return;
    setSavingData(true);
    try {
      const updated = addresses.filter((_, i) => i !== index);
      await updateDoc(doc(db, 'users', user.uid), {
        addresses: updated
      });
      setAddresses(updated);
    } catch (e) {
      console.error(e);
    } finally {
      setSavingData(false);
    }
