            <div className="text-[11px] font-bold text-[#7a5a52] mt-1 uppercase tracking-wide">Rewards</div>
          </TransitionLink>
        </div>

        <div className="px-5 mt-6 space-y-5">
          {/* Sektion 1: Persönliche Daten & Geburtstag */}
