'use client';

import React, { useState, useEffect } from 'react';
import { motion, Reorder, AnimatePresence } from 'framer-motion';
import { db } from '@/lib/firebase';
import { doc, updateDoc } from 'firebase/firestore';
import type { Order } from '@/types/firestore';
import { Clock, Check, ChevronRight } from 'lucide-react';

const STATUS_COLUMNS = ['pending', 'preparing', 'ready'] as const;

interface KanbanBoardProps {
  initialOrders: Order[];
}

export function KanbanBoard({ initialOrders }: KanbanBoardProps) {
  const [orders, setOrders] = useState<Order[]>(initialOrders);

  // Sync when real-time updates arrive
  useEffect(() => {
    setOrders(initialOrders);
  }, [initialOrders]);

  const updateOrderStatus = async (orderId: string, newStatus: string) => {
    // Optimistic update
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus as any } : o));
    try {
      await updateDoc(doc(db, 'orders', orderId), { status: newStatus });
    } catch (err) {
      console.error("Failed to update status:", err);
      // Revert on error
      setOrders(initialOrders);
    }
  };

  const handleAdvance = (order: Order) => {
    if (order.status === 'pending') updateOrderStatus(order.id, 'preparing');
    else if (order.status === 'preparing') updateOrderStatus(order.id, 'ready');
    else if (order.status === 'ready') updateOrderStatus(order.id, 'completed');
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[calc(100vh-140px)]">
      {STATUS_COLUMNS.map(column => {
        const columnOrders = orders.filter(o => o.status === column);

        let title = '';
        let bgColor = '';
        if (column === 'pending') { title = 'Eingegangen'; bgColor = 'bg-peach/30'; }
        if (column === 'preparing') { title = 'In Zubereitung'; bgColor = 'bg-[#E4C0A8]/40'; }
        if (column === 'ready') { title = 'Abholbereit'; bgColor = 'bg-terracotta/10 border-terracotta/20'; }

        return (
          <div key={column} className={`flex flex-col rounded-3xl ${bgColor} border border-peach/50 p-4`}>
            <div className="flex justify-between items-center mb-4 px-2">
              <h2 className="font-calistoga text-xl text-charcoal">{title}</h2>
              <span className="bg-white/60 text-charcoal font-bold px-3 py-1 rounded-full text-sm">
                {columnOrders.length}
              </span>
            </div>

            <div className="flex-1 overflow-y-auto hide-scrollbar">
              <Reorder.Group 
                axis="y" 
                values={columnOrders} 
                onReorder={(newOrder) => {
                  // If we just want reordering within the same column:
                  // We would update local state here. For simplicity in this demo,
                  // cross-column drag is tricky with basic Reorder.Group, so we rely on the Advance button
                  // and simple intra-column sorting if needed.
                }}
                className="flex flex-col gap-3 min-h-[50%]"
              >
                <AnimatePresence>
                  {columnOrders.map(order => (
                    <Reorder.Item 
                      key={order.id} 
                      value={order}
                      className="bg-cream rounded-2xl p-4 shadow-sm border border-white relative cursor-grab active:cursor-grabbing"
                    >
                      <div className="flex justify-between items-start mb-2">
                        <span className="font-black text-charcoal text-sm">#{order.id.slice(-5).toUpperCase()}</span>
                        <div className="flex items-center gap-1 text-terracotta font-bold text-sm bg-terracotta/10 px-2 py-0.5 rounded-md">
                          <Clock className="w-3 h-3" />
                          {order.time}
                        </div>
                      </div>

                      <div className="mb-3">
                        <p className="font-bold text-charcoal line-clamp-1">{order.name}</p>
                        {order.items.map((item, idx) => (
                          <p key={idx} className="text-xs text-charcoal/70 font-bold leading-tight mt-1">
                            {item.quantity}x {item.name}
                          </p>
                        ))}
                      </div>

                      <div className="flex justify-between items-center mt-4 pt-3 border-t border-peach/50">
                        <span className="font-calistoga text-terracotta">
                          {order.total.toFixed(2).replace('.', ',')} €
                        </span>

                        <button 
                          onClick={() => handleAdvance(order)}
                          className="bg-charcoal text-cream w-8 h-8 rounded-full flex items-center justify-center hover:bg-terracotta transition-colors"
                        >
                          {column === 'ready' ? <Check className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                        </button>
                      </div>
                    </Reorder.Item>
                  ))}
                </AnimatePresence>
              </Reorder.Group>
            </div>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import React, { useRef } from 'react';
import Image from 'next/image';
import { useAchievements } from '@/store/useAchievements';
import {
  LogoOrange,
  LogoBeige,
  LogoHellbeige,
  LogoRundBeige,
  LogoWortmarkeBeige,
  FormBeige
} from '@/assets/svg';
import { twMerge } from 'tailwind-merge';

type LogoVariant = 'orange' | 'beige' | 'hellbeige' | 'rund' | 'wortmarke' | 'form';

interface LogoProps extends Omit<React.SVGProps<SVGSVGElement>, 'onClick'> {
  variant?: LogoVariant;
  pulse?: boolean;
  onClick?: (e: React.MouseEvent<HTMLElement>) => void;
}

export function Logo({ variant = 'orange', pulse = false, className, onClick, ...props }: LogoProps) {
  const clicks = useRef<number[]>([]);

  const handleTap = (e: React.MouseEvent<HTMLElement>) => {
    const now = Date.now();
    clicks.current.push(now);
    clicks.current = clicks.current.filter(t => now - t <= 500);

    if (clicks.current.length >= 3) {
      const unlock = useAchievements.getState().unlock;
      unlock('sweet-tooth');
      clicks.current = [];
    }

    if (onClick) onClick(e);
  };

  if (variant === 'orange' || !variant) {
    return (
      <div
        onClick={handleTap}
        style={{ aspectRatio: "429.455 / 444.526" }}
        className={twMerge(
          "cursor-pointer transition-transform active:scale-95 relative",
          pulse && "animate-fede-pulse",
          className
        )}
        {...(props as any)}
      >
        <Image 
          src="/logo-orange.svg"
          alt="Hey Fede! Logo"
          fill
          priority
          style={{ objectFit: 'contain' }}
        />
      </div>
    );
  }

  let SvgIcon = LogoOrange;
  let ratio = "429.455 / 444.526"; // Default normal logo ratio

  switch (variant) {
    case 'beige':
      SvgIcon = LogoBeige;
      break;
    case 'hellbeige':
      SvgIcon = LogoHellbeige;
      break;
    case 'rund':
      SvgIcon = LogoRundBeige;
      ratio = "1 / 1";
      break;
    case 'wortmarke':
      SvgIcon = LogoWortmarkeBeige;
      ratio = "627.846 / 159.151";
      break;
    case 'form':
      SvgIcon = FormBeige;
      ratio = "1 / 1"; 
      break;
  }

  return (
    <SvgIcon
      onClick={handleTap as any}
      style={{ aspectRatio: ratio }}
      className={twMerge(
        "cursor-pointer transition-transform active:scale-95",
        pulse && "animate-fede-pulse",
        className
      )}
      {...props}
    />
  );
}

import React from 'react';
import { render, screen, fireEvent, act } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { Logo } from '../Logo';
import { ScallopBadge } from '../ScallopBadge';
import { PrimaryCTA } from '../buttons/PrimaryCTA';
import { useAchievements } from '@/store/useAchievements';

// Mock framer-motion to avoid animation issues in jsdom
vi.mock('framer-motion', async () => {
  const actual = await vi.importActual('framer-motion');
  return {
    ...actual,
    useReducedMotion: () => false,
  };
});

// Mock SVGs to avoid parsing issues in jsdom
vi.mock('@/assets/svg', () => ({
  LogoOrange: (props: any) => <svg data-testid="svg-mock" {...props} />,
  LogoBeige: (props: any) => <svg data-testid="svg-mock" {...props} />,
  LogoHellbeige: (props: any) => <svg data-testid="svg-mock" {...props} />,
  LogoRundBeige: (props: any) => <svg data-testid="svg-mock" {...props} />,
  LogoWortmarkeBeige: (props: any) => <svg data-testid="svg-mock" {...props} />,
  FormBeige: (props: any) => <svg data-testid="svg-mock" {...props} />,
}));

describe('Atoms', () => {
  describe('Logo', () => {
    it('should set default aspect-ratio', () => {
      render(<Logo data-testid="logo" />);
      const logo = screen.getByTestId('logo');
      expect(logo).toHaveStyle({ aspectRatio: '429.455 / 444.526' });
    });

    it('should change aspect-ratio based on variant', () => {
      const { unmount } = render(<Logo variant="rund" data-testid="logo-rund" />);
      expect(screen.getByTestId('logo-rund')).toHaveStyle({ aspectRatio: '1 / 1' });
      unmount();

      render(<Logo variant="wortmarke" data-testid="logo-wortmarke" />);
      expect(screen.getByTestId('logo-wortmarke')).toHaveStyle({ aspectRatio: '627.846 / 159.151' });
    });

    it('should cover all other variants', () => {
      const { unmount: u1 } = render(<Logo variant="beige" data-testid="v1" />);
      expect(screen.getByTestId('v1')).toBeInTheDocument();
      u1();

      const { unmount: u2 } = render(<Logo variant="hellbeige" data-testid="v2" />);
      expect(screen.getByTestId('v2')).toBeInTheDocument();
      u2();

      const { unmount: u3 } = render(<Logo variant="form" data-testid="v3" />);
      expect(screen.getByTestId('v3')).toHaveStyle({ aspectRatio: '1 / 1' });
      u3();
    });

    it('should unlock sweet-tooth achievement on triple tap', () => {
      vi.useFakeTimers();

      const unlockSpy = vi.spyOn(useAchievements.getState(), 'unlock');
      render(<Logo data-testid="logo-click" />);
      const logo = screen.getByTestId('logo-click');

      fireEvent.click(logo);
      vi.advanceTimersByTime(100);
      fireEvent.click(logo);
      vi.advanceTimersByTime(100);
      fireEvent.click(logo);

      expect(unlockSpy).toHaveBeenCalledWith('sweet-tooth');

      vi.useRealTimers();
    });
  });

  describe('ScallopBadge', () => {
    it('should apply rotate style', () => {
      render(
        <div data-testid="scallop-wrapper">
          <ScallopBadge rotate={45} />
        </div>
      );
      const container = screen.getByTestId('scallop-wrapper').firstElementChild as HTMLElement;
      expect(container).toHaveStyle({ transform: 'rotate(45deg)' });
    });

    it('should render children', () => {
      render(<ScallopBadge>Test Badge</ScallopBadge>);
      expect(screen.getByText('Test Badge')).toBeInTheDocument();
    });
  });

  describe('PrimaryCTA', () => {
    beforeEach(() => {
      vi.useFakeTimers();
    });

    afterEach(() => {
      vi.useRealTimers();
    });

    it('should render children and arrow if showArrow is true', () => {
      render(<PrimaryCTA showArrow>Click Me</PrimaryCTA>);
      expect(screen.getByText('Click Me')).toBeInTheDocument();
      // Arrow is rendered as a chevron icon (svg)
      expect(document.querySelector('svg')).toBeInTheDocument();
    });

    it('should trigger particle burst and call onClick', () => {
      const onClickMock = vi.fn();
      render(<PrimaryCTA onClick={onClickMock}>Click Me</PrimaryCTA>);

      const button = screen.getByRole('button', { name: 'Click Me' });

      act(() => {
        fireEvent.click(button);
      });

      expect(onClickMock).toHaveBeenCalled();

      act(() => {
        vi.advanceTimersByTime(800);
      });
    });
  });
});

