              pointerEvents: "none",
              willChange: "transform",
            }}
          >
            <IconComponent
              size={item.size * 0.45}
              color="#fff"
              strokeWidth={2}
            />
          </div>
        );
      })}
    </div>
  );
}

"use client";

import React, { useRef, useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Star, Quote, ExternalLink } from "lucide-react";
import { WaveDivider } from "@/components/ui/WaveDivider";
import { FadeUp } from "@/components/ui/FadeUp";
import { SectionTitle } from "@/components/ui/LayoutBlocks";

interface Review {
  id: string;
  name: string;
  stars: number;
  text: string;
}

const AVATAR_COLORS = ["#CC624C", "#5c3d35", "#E4C0A8", "#9a7060", "#3a2820"];

function getInitials(name: string) {
  return name
    .split(" ")
    .map((n) => n[0])
    .join("")
    .toUpperCase();
}

function ReviewCard({
  review,
  index,
  isTouch,
}: {
  review: Review;
  index: number;
  isTouch: boolean;
}) {
  const [isHovered, setIsHovered] = useState(false);
  const avatarColor = AVATAR_COLORS[index % AVATAR_COLORS.length];

  return (
    <motion.div
      onHoverStart={() => setIsHovered(true)}
      onHoverEnd={() => setIsHovered(false)}
      whileHover={isTouch ? undefined : { y: -8, scale: 1.02 }}
      whileTap={isTouch ? { scale: 0.97 } : undefined}
      transition={{ type: "spring", stiffness: 300, damping: 22 }}
      style={{
        background: "#f5efe8",
        borderRadius: 22,
        padding: "28px 24px",
        minWidth: 310,
        maxWidth: 350,
        flexShrink: 0,
        cursor: "default",
        boxShadow: isHovered
          ? "0 16px 40px rgba(204,98,76,0.18)"
          : "0 4px 18px rgba(45,31,25,0.07)",
        transition: "box-shadow 0.3s ease",
        position: "relative" as const,
        overflow: "hidden" as const,
        ...(isTouch ? { scrollSnapAlign: "start" as const } : {}),
      }}
    >
      {/* Decorative quote mark */}
      <motion.div
        animate={{
          opacity: isHovered ? 0.12 : 0.06,
          scale: isHovered ? 1.1 : 1,
        }}
        transition={{ duration: 0.3 }}
        style={{
          position: "absolute",
          top: 16,
          right: 16,
          color: "#CC624C",
        }}
      >
        <Quote size={48} strokeWidth={1.5} />
      </motion.div>

      {/* Stars with stagger animation */}
      <div
        style={{ display: "flex", gap: 3, marginBottom: 16 }}
        aria-label={`${review.stars} von 5 Sternen`}
        role="img"
      >
        {Array(review.stars)
          .fill(0)
          .map((_, j) => (
            <motion.div
              key={j}
              initial={{ opacity: 0, y: -8 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: j * 0.08, duration: 0.3 }}
            >
              <Star
                size={15}
                fill="#CC624C"
                color="#CC624C"
                aria-hidden="true"
              />
            </motion.div>
          ))}
      </div>

      {/* Review text */}
      <p
        style={{
          fontFamily: "var(--font-nunito), sans-serif",
          fontSize: "0.9rem",
          color: "#5c3d35",
          lineHeight: 1.72,
          marginBottom: 20,
          fontStyle: "italic",
          position: "relative" as const,
          zIndex: 1,
        }}
      >
        „{review.text}"
      </p>

      {/* Author row */}
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        {/* Avatar circle with initials */}
        <motion.div
          whileHover={{ rotate: [0, -5, 5, 0] }}
          transition={{ duration: 0.4 }}
          style={{
            width: 40,
            height: 40,
            borderRadius: "50%",
            background: avatarColor,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            color: "#fefefe",
            fontFamily: "var(--font-calistoga), serif",
            fontSize: "0.85rem",
            flexShrink: 0,
          }}
        >
          {getInitials(review.name)}
        </motion.div>
        <div>
          <div
            style={{
              fontFamily: "var(--font-nunito), sans-serif",
              fontWeight: 800,
              fontSize: "0.88rem",
