  setDoc: vi.fn(),
  getDoc: vi.fn().mockResolvedValue({ exists: () => false }),
}));

describe("useAchievements", () => {
  beforeEach(() => {
    useAchievements.setState({ unlocked: [] });
  });

  it("should unlock a new achievement", async () => {
    await useAchievements.getState().unlock("sweet-tooth");
    expect(useAchievements.getState().isUnlocked("sweet-tooth")).toBe(true);
    expect(useAchievements.getState().unlocked).toContain("sweet-tooth");
  });

  it("should not unlock an already unlocked achievement", async () => {
    useAchievements.setState({ unlocked: ["early-bird"] });
    await useAchievements.getState().unlock("early-bird");

    expect(useAchievements.getState().unlocked).toHaveLength(1);
    expect(useAchievements.getState().unlocked).toContain("early-bird");
  });

  it("should set unlocked achievements in bulk", () => {
    useAchievements.getState().syncFromFirebase(["loyal-fan", "waffle-master"]);
    expect(useAchievements.getState().unlocked).toEqual([
      "loyal-fan",
      "waffle-master",
    ]);
  });

  it("should sync to firebase if user is logged in", async () => {
    // Mock user
    (global as any).mockCurrentUser = { uid: "user123" };

    await useAchievements.getState().unlock("sweet-tooth");

    // verify updateDoc was called
    expect(firestore.updateDoc).toHaveBeenCalled();

    (global as any).mockCurrentUser = null; // cleanup
  });
});

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { ACHIEVEMENTS, type AchievementId } from '@/lib/achievements';
import { auth, db } from '@/lib/firebase';
import { doc, updateDoc, arrayUnion, setDoc, getDoc } from 'firebase/firestore';

interface AchievementsState {
  unlocked: string[];
  unlock: (id: AchievementId) => Promise<void>;
  isUnlocked: (id: AchievementId) => boolean;
  syncFromFirebase: (firebaseUnlocked: string[]) => void;
}

export const useAchievements = create<AchievementsState>()(
  persist(
    (set, get) => ({
      unlocked: [],

      syncFromFirebase: (firebaseUnlocked) => {
        set({ unlocked: Array.from(new Set([...get().unlocked, ...firebaseUnlocked])) });
      },

      unlock: async (id) => {
        const state = get();
        if (state.unlocked.includes(id)) return; // prevent duplicate unlock locally

        // Unlock locally first for immediate feedback
        set({ unlocked: [...state.unlocked, id] });

        // Dispatch event for UI banners
        if (typeof window !== 'undefined') {
          window.dispatchEvent(new CustomEvent('achievementUnlocked', { detail: id }));
        }

        // Sync to Firebase if user is logged in
        const user = auth.currentUser;
        if (user) {
          try {
            const userRef = doc(db, 'users', user.uid);
            await updateDoc(userRef, {
              achievements: arrayUnion(id)
            });

            // Reward coins if any
            const achievement = ACHIEVEMENTS[id];
            if (achievement && achievement.coinReward && achievement.coinReward > 0) {
              const lpRef = doc(db, 'loyalty_points', user.uid);
              const lpSnap = await getDoc(lpRef);

              const newEntry = {
                amount: achievement.coinReward,
                type: 'earned',
                date: new Date(),
                reason: `Achievement: ${achievement.title}`
              };

              if (lpSnap.exists()) {
                const data = lpSnap.data();
                await updateDoc(lpRef, {
                  balance: (data.balance || 0) + achievement.coinReward,
                  history: arrayUnion(newEntry)
                });
              } else {
                await setDoc(lpRef, {
                  uid: user.uid,
                  balance: achievement.coinReward,
                  history: [newEntry]
                });
              }
            }
          } catch (err) {
            console.error("Failed to sync achievement to Firestore", err);
          }
        }
      },

      isUnlocked: (id) => get().unlocked.includes(id),
    }),
    {
      name: 'hey-fede-achievements',
    }
  )
);

// Global listener for sweet-tooth logo taps
if (typeof window !== 'undefined') {
  window.addEventListener('achievementUnlocked', (e) => {
    // This is to catch the event from Logo.tsx which doesn't have access to the store directly
    // Wait, Logo.tsx already dispatches it. If Logo dispatches it, and the store listens to it, 
    // it will unlock it. But wait, we shouldn't infinitely loop. Logo.tsx dispatches `achievementUnlocked`.
    // We want Logo.tsx to call `useAchievements.getState().unlock('sweet-tooth')`.
    // But Logo is a component. It can just use the hook.
  });
}

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export type CartItem = {
  id: string;
  name: string;
  price: number;
  quantity: number;
  variant?: string;
};

interface OrderData {
  orderId?: string;
  orderNumber?: string;
  pickupDate?: string;
  pickupTime?: string;
  name?: string;
  phone?: string;
  email?: string;
  notes?: string;
  address?: {
    street: string;
    zip: string;
    city: string;
  };
  promoCode?: string;
  discountValue?: number;
}

export type OrderType = "pickup" | "delivery" | "in-store" | null;

interface StoreState {
  cart: CartItem[];
  isCartOpen: boolean;
  orderType: OrderType;
  orderData: OrderData;
  addToCart: (item: Omit<CartItem, 'quantity'>) => void;
  removeFromCart: (id: string) => void;
  updateQuantity: (id: string, q: number) => void;
  openCart: () => void;
  closeCart: () => void;
  toggleCart: () => void;
  clearCart: () => void;
  setOrderType: (type: OrderType) => void;
  setCart: (cart: CartItem[]) => void;
  updateOrderData: (data: Partial<OrderData>) => void;
  clearOrderData: () => void;
  total: number;
}

const computeTotal = (cart: CartItem[]) => cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

export const useStore = create<StoreState>()(
  persist(
    (set, get) => ({
      cart: [],
      isCartOpen: false,
      orderType: null,
      orderData: {},
      total: 0,
      addToCart: (item) => set((s) => {
        const exists = s.cart.find(c => c.id === item.id);
        const newCart = exists
          ? s.cart.map(c => c.id === item.id ? { ...c, quantity: c.quantity + 1 } : c)
          : [...s.cart, { ...item, quantity: 1 }];
        return { cart: newCart, total: computeTotal(newCart) };
      }),
      removeFromCart: (id) => set((s) => {
        const newCart = s.cart.filter(c => c.id !== id);
        return { cart: newCart, total: computeTotal(newCart) };
      }),
      updateQuantity: (id, q) => set((s) => {
        const newCart = q <= 0
          ? s.cart.filter(c => c.id !== id)
          : s.cart.map(c => c.id === id ? { ...c, quantity: q } : c);
        return { cart: newCart, total: computeTotal(newCart) };
      }),
      openCart: () => set({ isCartOpen: true }),
      closeCart: () => set({ isCartOpen: false }),
      toggleCart: () => set((s) => ({ isCartOpen: !s.isCartOpen })),
      clearCart: () => set({ cart: [], total: 0 }),
      setCart: (cart) => set({ cart, total: computeTotal(cart) }),
      setOrderType: (type) => set({ orderType: type }),
      updateOrderData: (data) => set((s) => ({ orderData: { ...s.orderData, ...data } })),
      clearOrderData: () => set({ orderData: {}, orderType: null }),
    }),
    {
      name: 'hey-fede-cart',
      partialize: (state) => ({ cart: state.cart, orderType: state.orderType, orderData: state.orderData })
    }
  )
);

